public sealed class MoveItemSpaceProtocolCommandFlowTests(ITestOutputHelper output)
{
    // The same driver and observations run on the original registered fine and migrated whole.
    [Theory]
    [InlineData("split",14)] [InlineData("merge",18)] [InlineData("swap",24)] [InlineData("reverse",24)]
    [InlineData("identical",18)] [InlineData("wear",24)] [InlineData("takeoff",18)]
    [InlineData("personal",24)] [InlineData("account",18)] [InlineData("shared",24)]
    public async Task Real_move_wire_preserves_complete_assets_UIDs_and_ordered_frames(string mode,int length)
    {
        var t=new Trace();using var f=Fixture(t);int from=65,into=3,count=3;byte fl=0,tl=0;
        if(mode=="reverse"){await f.Seed(3,5000,7);count=0;}
        else if(mode is "identical" or "wear" or "takeoff")
        {
            var core=StackableItemCore.Create(1,3000,1234)with{Durability=17,EnchantCardId=41};from=9;into=10;count=1;
            if(mode=="identical"){await f.SeedCore(9,core);await f.SeedCore(10,core);}
            else if(mode=="wear"){await f.SeedCore(9,core);tl=3;into=12;}
            else{await f.SeedCore(12,core,InventoryContainerType.Equipment);fl=3;from=12;into=9;}
        }
        else{if(mode=="shared"){await f.SeedShared(3037,7);from=358;tl=2;into=0;}else{await f.Seed(65,5000,7);if(mode=="merge")await f.Seed(3,5000,2);if(mode=="swap"){await f.Seed(3,2000,2);count=0;}if(mode is "personal" or "account"){tl=mode=="personal"?(byte)2:(byte)12;into=0;}}}
        var before=await Assets(f);var firstUID=mode=="identical"?f.Scalar("SELECT core_uid FROM item_slots WHERE list_type=0 AND slot_index=9"):0;var secondUID=mode=="identical"?f.Scalar("SELECT core_uid FROM item_slots WHERE list_type=0 AND slot_index=10"):0;
        await MoveWire.Send(f,fl,from,tl,into,count,length:length,trace:t);
        var ack=Assert.IsType<MoveItemSpaceResponse>(f.Sender.Messages[0]);Assert.Null(ack.ErrorCode);Assert.Equal(new GameSlot((InventoryContainerType)fl,from),ack.SourceSlot);
        if(mode=="split"){Assert.Equal(4,SlotCount(f,0,65));Assert.Equal(3,SlotCount(f,0,3));}
        if(mode=="merge"){Assert.Equal(4,SlotCount(f,0,65));Assert.Equal(5,SlotCount(f,0,3));}
        if(mode=="reverse"){Assert.Equal(7,SlotCount(f,0,65));Assert.Equal(0,SlotCount(f,0,3));}
        if(mode=="identical"){Assert.NotEqual(firstUID,secondUID);Assert.Equal(secondUID,f.Scalar("SELECT core_uid FROM item_slots WHERE list_type=0 AND slot_index=9"));Assert.Equal(firstUID,f.Scalar("SELECT core_uid FROM item_slots WHERE list_type=0 AND slot_index=10"));}
        if(mode is "wear" or "takeoff")Assert.Equal(3,Assert.Single(f.Sender.Outbound.Explicits).Delivery.RequiredDirectMessages.Count);
        if(mode is "personal" or "account" or "shared")Assert.Equal(3,Assert.Single(f.Sender.Outbound.Explicits).Delivery.RequiredDirectMessages.Count);
        Assert.Same(f.Connection,Assert.Single(f.Sender.Outbound.Entries).Connection);AssertNoLedger(f);
        Write("success",new{mode,length,before,after=await Assets(f),attempts=Attempts(t),postReads=t.PostReads,inputs=t.Inputs,frames=Frames(f)});
    }
    [Theory] [InlineData(false)] [InlineData(true)]
    public async Task Second_end_SQL_and_actual_native_Commit_restore_the_complete_move_and_retry(bool native)
    {
        var t=new Trace{Native=native};using var f=Fixture(t);await f.Seed(65,5000,7);var before=await Assets(f);
        var ddl=native?"CREATE TABLE move_parent(id INTEGER PRIMARY KEY);CREATE TABLE move_child(id INTEGER REFERENCES move_parent(id) DEFERRABLE INITIALLY DEFERRED);CREATE TRIGGER move_fault AFTER INSERT ON item_slots WHEN NEW.owner_scope='character' AND NEW.owner_id=1 AND NEW.list_type=0 AND NEW.slot_index=3 BEGIN INSERT INTO move_child VALUES(404);END;":"CREATE TRIGGER move_fault BEFORE INSERT ON item_slots WHEN NEW.owner_scope='character' AND NEW.owner_id=1 AND NEW.list_type=0 AND NEW.slot_index=3 BEGIN SELECT RAISE(ABORT,'move second end SQL failure');END;";
        f.Sql(ddl);var error=await Record.ExceptionAsync(()=>MoveWire.Send(f,0,65,0,3,3,sequence:7,trace:t).AsTask());var cause=Assert.IsType<SqliteException>(error);Assert.Equal(19,cause.SqliteErrorCode);Assert.Equal(native?787:1811,cause.SqliteExtendedErrorCode);var a=Assert.Single(t.Attempts);Assert.Equal(native,a.Completed);Assert.Equal(1,a.ForeignKeys);Assert.Equal(DomainTransactionCompletion.ConfirmedRollback,a.Tx.Completion);Assert.Equal(before,await Assets(f));
        if(native){Assert.True(a.Children>0);Assert.Equal(4,a.SourceCount);Assert.Equal(3,a.DestinationCount);Assert.Same(cause,a.Tx.CommitFailure!.Cause);SqliteFailureAssertions.FromCommit(a.Tx, cause);}else{Assert.Same(cause,a.Failure);Assert.Equal(4,a.SourceCount);SqliteFailureAssertions.FromAction(a.Tx, cause);}
        Assert.Empty(f.Sender.Messages);var close=Assert.Single(f.Sender.Outbound.Entries);Assert.True(close.IsClose);Assert.Same(f.Connection,close.Connection);Assert.True(GameplayJob.EndedAJob(cause));Assert.False(f.Services.GetRequiredService<SelectedSessionSafety>().IsBlocked(f.Connection));AssertNoLedger(f);
        var fault=new{native,ddl,before,after=await Assets(f),attempts=Attempts(t),cause=cause.ToString(),causeSame=ReferenceEquals(cause,native?a.Tx.CommitFailure!.Cause:a.Failure),sourceCloseExact=ReferenceEquals(f.Connection,close.Connection),inputs=t.Inputs.ToArray()};f.Sql("DROP TRIGGER move_fault");await MoveWire.Send(f,0,65,0,3,3,sequence:7,trace:t);Assert.Equal(4,SlotCount(f,0,65));Assert.Equal(3,SlotCount(f,0,3));Assert.False(t.Inputs.Last().SequenceIsFresh);Write("sql",new{fault,afterRetry=await Assets(f),inputs=t.Inputs,frames=Frames(f)});
    }
    [Theory] [InlineData("cargo")] [InlineData("appearance")] [InlineData("housing")]
    public async Task Original_post_commit_catches_keep_ACK_and_already_appended_appearance(string stage)
    {
        var t=new Trace{FaultStage=stage};using var f=Fixture(t);if(stage=="cargo")await f.Seed(65,5000,7);else await f.SeedCore(9,StackableItemCore.Create(1,3000,1234));
        var error=await Record.ExceptionAsync(()=>MoveWire.Send(f,0,stage=="cargo"?65:9,stage=="cargo"?(byte)2:(byte)3,stage=="cargo"?0:12,stage=="cargo"?3:1,trace:t).AsTask());Assert.Null(error);Assert.Null(Assert.IsType<MoveItemSpaceResponse>(f.Sender.Messages[0]).ErrorCode);Assert.Single(t.Logs,x=>x.Level==LogLevel.Error&&ReferenceEquals(x.Error,t.Cause));Assert.Equal(stage=="housing"?3:1,Assert.Single(f.Sender.Outbound.Explicits).Delivery.RequiredDirectMessages.Count);Assert.All(t.PostReads,x=>Assert.False(x.Open));Assert.Empty(f.Sender.Outbound.Closes);Assert.False(f.Services.GetRequiredService<SelectedSessionSafety>().IsBlocked(f.Connection));AssertNoLedger(f);Write("postFault",new{stage,assets=await Assets(f),attempts=Attempts(t),postReads=t.PostReads,inputs=t.Inputs,frames=Frames(f),errorSame=t.Logs.Any(x=>x.Level==LogLevel.Error&&ReferenceEquals(x.Error,t.Cause))});
    }
    [Theory] [InlineData("no-session")] [InlineData("refused")] [InlineData("success")]
    public async Task Actual_explicit_encoder_fault_preserves_cause_close_and_default_committed_envelope(string branch)
    {
        var t=new Trace{MissingSession=branch=="no-session"};using var f=Fixture(t);if(branch=="success")await f.Seed(65,5000,7);var before=await Assets(f);int calls=0;f.Sender.Outbound.Encoder.Fail((target,_)=>{Assert.Same(f.Connection,target);t.Chain=GameplayJob.Current;calls++;return t.Cause;});
        var error=await Record.ExceptionAsync(()=>MoveWire.Send(f,0,65,0,3,3,trace:t).AsTask());
        if(branch!="no-session"&&t.Contexts.Count>0){var typed=Assert.IsType<TransactionOutcomeUncertainException>(error);Assert.Equal(TransactionUncertaintyReason.PostCommitPublicationFailure,typed.Reason);Assert.Same(t.Cause,typed.InnerException);var req=Assert.IsType<CommandRequestContext.ProtocolNonEffect>(t.Contexts.Single().Request);Assert.True(req.IsClosed);Assert.True(req.HasCommittedUnit);Assert.Empty(req.CommittedParticipants);Assert.Empty((System.Collections.ICollection)typeof(CommandRequestContext).GetField("attempts",BindingFlags.Instance|BindingFlags.NonPublic)!.GetValue(req)!);}else Assert.Same(t.Cause,error);
        Assert.True(GameplayJob.EndedAJob(error!));Assert.Equal(1,calls);Assert.Empty(f.Sender.Messages);var close=Assert.Single(f.Sender.Outbound.Entries);Assert.True(close.IsClose);Assert.Same(f.Connection,close.Connection);Assert.False(f.Services.GetRequiredService<SelectedSessionSafety>().IsBlocked(f.Connection));AssertNoLedger(f);if(branch!="success")Assert.Equal(before,await Assets(f));else{Assert.Equal(4,SlotCount(f,0,65));Assert.Equal(3,SlotCount(f,0,3));}
        var chain=t.Chain!.Value;var log=Assert.Single(t.Logs,x=>x.Level==LogLevel.Error&&ReferenceEquals(x.Error,error));Assert.True(chain.IsInitialized);Assert.Null(chain.ParentId);Assert.Equal(0,chain.Depth);Assert.Equal(f.Connection.ConnectionId,chain.SourceConnection);foreach(var pair in new Dictionary<string,object?>{{"RootId",chain.RootId},{"ParentId",chain.ParentId},{"Depth",chain.Depth},{"Source",chain.Source},{"SourceConnection",chain.SourceConnection},{"CommandType",chain.CommandType}})Assert.Equal(pair.Value,log.Fields[pair.Key]);Write("encoder",new{branch,before,after=await Assets(f),cause=error!.ToString(),causeSame=ReferenceEquals(error is TransactionOutcomeUncertainException ex?ex.InnerException:error,t.Cause),typed=TransactionOutcomeUncertainException.Contains(error),reason=(error as TransactionOutcomeUncertainException)?.Reason.ToString(),chain,attempts=Attempts(t),inputs=t.Inputs,frames=Frames(f),sourceCloseExact=ReferenceEquals(f.Connection,close.Connection)});
    }
    [Theory] [InlineData(false)] [InlineData(true)]
    public async Task Same_identity_restatement_does_not_reverse_the_committed_item(bool restatement)
    {var t=new Trace();using var f=Fixture(t);await f.Seed(65,5000,7);await MoveWire.Send(f,0,65,0,3,0,sourceIdentity:5000,sequence:7,trace:t);if(restatement)await MoveWire.Send(f,0,65,0,3,0,sourceIdentity:5000,sequence:7,trace:t);var actualSource=SlotCount(f,0,65);var actualDestination=SlotCount(f,0,3);Write("mutationAsset",new{restatement,actualSource,actualDestination,assets=await Assets(f),attempts=Attempts(t),inputs=t.Inputs,frames=Frames(f)});Assert.Equal(0,actualSource);Assert.Equal(7,actualDestination);if(restatement){Assert.Equal(MoveItemSpaceResponse.Silent,Assert.IsType<MoveItemSpaceResponse>(f.Sender.Messages.Last()).ErrorCode);Assert.False(t.Inputs.Last().SequenceIsFresh);}AssertNoLedger(f);}
    [Fact]
    public async Task NonEffect_same_sequence_accepts_new_reverse_input_from_current_facts()
    {var t=new Trace();using var f=Fixture(t);await f.Seed(65,5000,7);await MoveWire.Send(f,0,65,0,3,0,sourceIdentity:5000,sequence:7,trace:t);await MoveWire.Send(f,0,3,0,65,0,sourceIdentity:5000,sequence:7,trace:t);Assert.Equal(7,SlotCount(f,0,65));Assert.Equal(0,SlotCount(f,0,3));Assert.False(t.Inputs.Last().SequenceIsFresh);AssertNoLedger(f);Write("sameSeq",new{assets=await Assets(f),attempts=Attempts(t),inputs=t.Inputs,frames=Frames(f)});}

    private void Write(string kind,object data)=>output.WriteLine(JsonSerializer.Serialize(new{task26=true,kind,data}));
    private static int SlotCount(ShopFixture f,int list,int slot)=>f.Scalar($"SELECT COALESCE(SUM(count),0) FROM item_slots WHERE owner_scope='character' AND owner_id=1 AND list_type={list} AND slot_index={slot}");
    private static string[] Frames(ShopFixture f)=>f.Sender.Outbound.Frames.Select(Convert.ToHexString).ToArray();
    private static object[] Attempts(Trace t)=>t.Attempts.Select(a=>(object)new{completion=a.Tx.Completion.ToString(),a.Completed,failure=a.Failure?.ToString(),a.ForeignKeys,a.Children,a.SourceCount,a.DestinationCount,a.Stage,methods=a.Methods}).ToArray();
    private static ShopFixture Fixture(Trace t)=>WarehouseStorageTests.Fixture(s=>
    {
        var move=s.Last(x=>x.ServiceType==typeof(IItemMovementDomainService));s.AddSingleton<IItemMovementDomainService>(p=>MovementProxy.Create(Resolve<IItemMovementDomainService>(move,p),p,t));
        var cargo=s.Last(x=>x.ServiceType==typeof(ICargoTransferDomainService));s.AddSingleton<ICargoTransferDomainService>(p=>CargoProxy.Create(Resolve<ICargoTransferDomainService>(cargo,p),p,t));
        var character=s.Last(x=>x.ServiceType==typeof(ICharacterInventoryEntryDomainService));s.AddSingleton<ICharacterInventoryEntryDomainService>(p=>CharacterProxy.Create(Resolve<ICharacterInventoryEntryDomainService>(character,p),p,t));
        var selected=s.Last(x=>x.ServiceType==typeof(ISelectedSessionDomainService));s.AddSingleton<ISelectedSessionDomainService>(p=>SessionProxy.Create(Resolve<ISelectedSessionDomainService>(selected,p),t));
        s.AddSingleton<IEquipmentSlotDefinitionSource, Slots>();s.AddSingleton<IEquipmentWearDomainService, Wearing>();s.AddSingleton<ISelectedCharacterCurrentViewDomainService>(p=>new CurrentView(p,t));s.AddSingleton<IMarriageHousingQueryDomainService>(p=>new Housing(p,t));s.AddScoped<CommandWorkUnits>();s.AddScoped<ICommandWorkUnits>(p=>new Units(p.GetRequiredService<CommandWorkUnits>(),t));s.AddLogging(x=>x.AddProvider(new Logs(t)));
    }).WithAccountCargo();
    private static T Resolve<T>(ServiceDescriptor d,IServiceProvider p)where T:class=>(T)(d.ImplementationInstance??d.ImplementationFactory?.Invoke(p)??ActivatorUtilities.CreateInstance(p,d.ImplementationType!));
    internal sealed class Trace{internal readonly List<Attempt> Attempts=[];internal readonly List<MoveWireObservation> Inputs=[];internal readonly List<CommandExecutionContext> Contexts=[];internal readonly List<LogRow> Logs=[];internal readonly List<PostRead> PostReads=[];internal bool Capturing,Native,MissingSession;internal string? FaultStage;internal GameplayCallChain? Chain;internal readonly IOException Cause=new("fixed move publication or post-read failure");}
    internal sealed record Attempt(DomainTransaction Tx){internal bool Completed;internal Exception? Failure;internal int ForeignKeys,Children,SourceCount,DestinationCount;internal string? Stage;internal readonly List<string> Methods=[];}
    internal sealed record PostRead(string Name,bool Open);
    private static Attempt Begin(IServiceProvider p,Trace t,string method){var tx=Assert.IsType<DomainTransaction>(p.GetRequiredService<IDomainTransactionAccessor>().Current);Assert.False(tx.IsReadOnly);Assert.False(tx.IsSettled);var a=t.Attempts.SingleOrDefault(x=>ReferenceEquals(x.Tx,tx));if(a is null){a=new(tx);t.Attempts.Add(a);}a.Methods.Add(method);return a;}
    private static async ValueTask<ItemMoveOutcome> Watch(ValueTask<ItemMoveOutcome> pending,IServiceProvider p,Trace t,Attempt a){ItemMoveOutcome? result=null;try{result=await pending;a.Completed=true;return result;}catch(Exception ex){a.Failure=ex;throw;}finally{if(result is ItemMoveOutcome.Moved||a.Failure!=null){a.ForeignKeys=await Scalar(p,"PRAGMA foreign_keys",default);a.Children=t.Native?await Scalar(p,"SELECT count(*) FROM move_child",default):0;a.SourceCount=await Scalar(p,"SELECT COALESCE(SUM(count),0) FROM item_slots WHERE owner_scope='character' AND owner_id=1 AND list_type=0 AND slot_index=65",default);a.DestinationCount=await Scalar(p,"SELECT COALESCE(SUM(count),0) FROM item_slots WHERE owner_scope='character' AND owner_id=1 AND list_type=0 AND slot_index=3",default);a.Stage=await AssetsIn(p,default);}}}
    public class MovementProxy:DispatchProxy{private IItemMovementDomainService actual=null!;private IServiceProvider p=null!;private Trace t=null!;internal static IItemMovementDomainService Create(IItemMovementDomainService actual,IServiceProvider p,Trace t){var x=Create<IItemMovementDomainService,MovementProxy>();((MovementProxy)x).actual=actual;((MovementProxy)x).p=p;((MovementProxy)x).t=t;return x;}protected override object? Invoke(MethodInfo? m,object?[]? args){var a=t.Capturing?Begin(p,t,m!.Name):null;try{var value=m!.Invoke(actual,args);return a is not null&&value is ValueTask<ItemMoveOutcome> work?Watch(work,p,t,a):value;}catch(TargetInvocationException ex)when(ex.InnerException is{} cause){ExceptionDispatchInfo.Throw(cause);throw;}}}
    public class CargoProxy:DispatchProxy{private ICargoTransferDomainService actual=null!;private IServiceProvider p=null!;private Trace t=null!;internal static ICargoTransferDomainService Create(ICargoTransferDomainService actual,IServiceProvider p,Trace t){var x=Create<ICargoTransferDomainService,CargoProxy>();((CargoProxy)x).actual=actual;((CargoProxy)x).p=p;((CargoProxy)x).t=t;return x;}protected override object? Invoke(MethodInfo? m,object?[]? args){var a=t.Capturing?Begin(p,t,m!.Name):null;try{var value=m!.Invoke(actual,args);return a is not null&&value is ValueTask<ItemMoveOutcome> work?Watch(work,p,t,a):value;}catch(TargetInvocationException ex)when(ex.InnerException is{} cause){ExceptionDispatchInfo.Throw(cause);throw;}}}
    public class CharacterProxy:DispatchProxy{private ICharacterInventoryEntryDomainService actual=null!;private IServiceProvider p=null!;private Trace t=null!;internal static ICharacterInventoryEntryDomainService Create(ICharacterInventoryEntryDomainService actual,IServiceProvider p,Trace t){var x=Create<ICharacterInventoryEntryDomainService,CharacterProxy>();((CharacterProxy)x).actual=actual;((CharacterProxy)x).p=p;((CharacterProxy)x).t=t;return x;}protected override object? Invoke(MethodInfo? m,object?[]? args){if(t.Capturing){t.PostReads.Add(new(m!.Name,p.GetRequiredService<IDomainTransactionAccessor>().Current is not null));if(t.FaultStage=="cargo")throw t.Cause;}try{return m!.Invoke(actual,args);}catch(TargetInvocationException ex)when(ex.InnerException is{} cause){ExceptionDispatchInfo.Throw(cause);throw;}}}
    public class SessionProxy:DispatchProxy{private ISelectedSessionDomainService actual=null!;private Trace t=null!;internal static ISelectedSessionDomainService Create(ISelectedSessionDomainService actual,Trace t){var x=Create<ISelectedSessionDomainService,SessionProxy>();((SessionProxy)x).actual=actual;((SessionProxy)x).t=t;return x;}protected override object? Invoke(MethodInfo? m,object?[]? args){if(t.Capturing&&t.MissingSession&&m!.Name==nameof(ISelectedSessionDomainService.FindByConnection))return null;try{return m!.Invoke(actual,args);}catch(TargetInvocationException ex)when(ex.InnerException is{} cause){ExceptionDispatchInfo.Throw(cause);throw;}}}
    private sealed class CurrentView(IServiceProvider p,Trace t):ISelectedCharacterCurrentViewDomainService{public async ValueTask<SelectCharacterResult?> TryLoadAsync(SelectedSessionIdentity s,CancellationToken ct){t.PostReads.Add(new("CurrentView",p.GetRequiredService<IDomainTransactionAccessor>().Current is not null));if(t.FaultStage=="appearance")throw t.Cause;var baseline=await Characters.CharacterEntryInventoryTests.CreateLifecycleResultAsync(s.AccountId,s.CharacterId.Value,0);var inv=await p.GetRequiredService<ICharacterInventoryEntryDomainService>().ReadCurrentAsync(s.AccountId,s.CharacterId,ct);return baseline with{CharacterInventory=inv,CharacterEntry=baseline.CharacterEntry with{Skills=baseline.CharacterEntry.Skills with{ProtocolMirror=new(0,0,0,0)},Public=baseline.CharacterEntry.Public with{Identity=new(0,0,0)}}};}}
    private sealed class Housing(IServiceProvider p,Trace t):IMarriageHousingQueryDomainService{public ValueTask<HousingSnapshot?> ReadAsync(AccountId a,CharacterId c,CancellationToken ct){t.PostReads.Add(new("Housing",p.GetRequiredService<IDomainTransactionAccessor>().Current is not null));if(t.FaultStage=="housing")throw t.Cause;return ValueTask.FromResult<HousingSnapshot?>(null);}public ValueTask<MarriageInfoSnapshot?> InfoAsync(AccountId a,CharacterId c,CancellationToken ct)=>throw new NotSupportedException();public bool IsEntrySource(byte t,byte a)=>false;public ValueTask<int?> InstanceAsync(SelectedSessionIdentity a,CancellationToken ct)=>ValueTask.FromResult<int?>(null);public ValueTask<int> PointsAsync(AccountId a,CharacterId c,CancellationToken ct)=>ValueTask.FromResult(0);public ValueTask<byte> RingAsync(AccountId a,CharacterId c,CancellationToken ct)=>ValueTask.FromResult((byte)0);public ValueTask<HousingBenefits> BenefitsAsync(AccountId a,CharacterId c,bool pvp,CancellationToken ct)=>throw new NotSupportedException();}
