    private sealed class Wearing:IEquipmentWearDomainService{public ItemSnapshot UnsealForEquip(ItemSnapshot i)=>i;public ValueTask<bool> CanWearAsync(CharacterId c,int id,CancellationToken ct)=>ValueTask.FromResult(true);}
    private sealed class Units(ICommandWorkUnits actual,Trace t):ICommandWorkUnits{public ValueTask<T> WriteAsync<T>(CommandExecutionContext c,CommandWorkUnitDeclaration d,Func<CommandWorkUnit,CancellationToken,ValueTask<T>> a,CancellationToken ct=default)where T:notnull{var r=Assert.IsType<CommandRequestContext.ProtocolNonEffect>(c.Request);Assert.Empty(d.Participants);Assert.Equal(CommandWorkUnitKind.Ordinary,d.Kind);Assert.Equal(CommandFootprintMode.None,d.Footprint);Assert.Same(((MoveItemSpaceRequest)r.Message).Metadata,Assert.IsType<ProtocolFrameMetadata.Game>(r.Metadata).Value);t.Contexts.Add(c);return actual.WriteAsync(c,d,a,ct);}public ValueTask<CommandWriteResult<T>> WriteResultAsync<T>(CommandExecutionContext c,CommandWorkUnitDeclaration d,Func<CommandWorkUnit,CancellationToken,ValueTask<T>> a,CancellationToken ct=default)where T:notnull=>throw new InvalidOperationException("Move uses default ordinary Write.");public ValueTask<T> ReadOnlyAsync<T>(CommandExecutionContext c,CommandWorkUnitDeclaration d,Func<CancellationToken,ValueTask<T>> a,CancellationToken ct=default)where T:notnull=>throw new InvalidOperationException("Post reads have no new unit.");}
    internal sealed record LogRow(LogLevel Level,Exception? Error,string Message,IReadOnlyDictionary<string,object?> Fields);
    private sealed class Logs(Trace t):ILoggerProvider{public ILogger CreateLogger(string n)=>new L(t);public void Dispose(){}private sealed class L(Trace t):ILogger{public IDisposable? BeginScope<TState>(TState s)where TState:notnull=>null;public bool IsEnabled(LogLevel l)=>true;public void Log<TState>(LogLevel l,EventId id,TState s,Exception? e,Func<TState,Exception?,string> f)=>t.Logs.Add(new(l,e,f(s,e),s is IEnumerable<KeyValuePair<string,object?>> x?x.ToDictionary(v=>v.Key,v=>v.Value):new Dictionary<string,object?>()));}}
    private static void AssertNoLedger(ShopFixture f){var table=typeof(Dfo.Server.Application.Effects.EffectOperationLedger).GetField("ledgers",BindingFlags.Instance|BindingFlags.NonPublic)!.GetValue(f.Services.GetRequiredService<Dfo.Server.Application.Effects.EffectOperationLedger>())!;object?[] args=[f.Connection,null];Assert.False((bool)table.GetType().GetMethod("TryGetValue")!.Invoke(table,args)!);}
    internal static Task<string> Assets(ShopFixture f)=>TestGameplay.RunAsync(f.Services,async()=>await AssetsIn(f.Services,default));
    private static async ValueTask<string> AssetsIn(IServiceProvider p,CancellationToken ct){var result=new SortedDictionary<string,string>();foreach(var n in new[]{"items","item_slots","characters","character_stats","character_condition","character_container_state","account_cargo_state","character_rentals","equipment_rental_instances","domain_events","domain_event_deliveries"})result[n]=await Rows(p,"SELECT * FROM "+n,ct);return JsonSerializer.Serialize(result);}
    private static ValueTask<string> Rows(IServiceProvider p,string sql,CancellationToken ct)=>p.GetRequiredService<SqliteDatabase>().ReadAsync(async(cmd,token)=>{cmd.CommandText=sql;await using var reader=await cmd.ExecuteReaderAsync(token);var rows=new List<string>();while(await reader.ReadAsync(token))rows.Add(JsonSerializer.Serialize(Enumerable.Range(0,reader.FieldCount).ToDictionary(i=>reader.GetName(i),i=>reader.IsDBNull(i)?null:reader.GetValue(i)is byte[] blob?Convert.ToHexString(blob):Convert.ToString(reader.GetValue(i)))));rows.Sort(StringComparer.Ordinal);return "["+string.Join(",",rows)+"]";},ct);
    private static ValueTask<int> Scalar(IServiceProvider p,string sql,CancellationToken ct)=>p.GetRequiredService<SqliteDatabase>().ReadAsync(async(cmd,token)=>{cmd.CommandText=sql;return Convert.ToInt32(await cmd.ExecuteScalarAsync(token));},ct);
